// SPDX-License-Identifier: MPL-2.0

//! The core of the Asterinas kernel.
//!
//! This crate implements the Linux ABI and the core kernel mechanisms.

#![no_std]
#![deny(unsafe_code)]
#![feature(alloc_io)]
#![feature(array_try_from_fn)]
#![feature(associated_type_defaults)]
#![feature(btree_cursors)]
#![feature(debug_closure_helpers)]
#![feature(format_args_nl)]
#![feature(ip_as_octets)]
#![feature(linked_list_cursors)]
#![feature(linked_list_retain)]
#![feature(panic_can_unwind)]
#![feature(min_specialization)]
#![feature(thin_box)]
#![feature(unique_rc_arc)]
#![feature(custom_inner_attributes)]

extern crate alloc;
extern crate lru;
#[macro_use]
extern crate getset;
#[macro_use]
extern crate ostd_pod;

// Set this crate's log prefix for `ostd::log`.
macro_rules! __log_prefix {
    () => {
        ""
    };
}

#[cfg_attr(target_arch = "x86_64", path = "arch/x86/mod.rs")]
#[cfg_attr(target_arch = "riscv64", path = "arch/riscv/mod.rs")]
#[cfg_attr(target_arch = "loongarch64", path = "arch/loongarch/mod.rs")]
#[cfg_attr(target_arch = "aarch64", path = "arch/arm/mod.rs")]
mod arch;

// Single-source bridge to the experimental no_std HOS2 codec. This is
// deliberately NOT a second wire implementation. A01 can replace the path
// module with a locked Cargo path-dependency when the derived lock is updated.
#[path = "../../../../../libs/os-abi/src/lib.rs"]
#[allow(unused_attributes)]
pub(crate) mod hos2_os_abi;

pub mod context;
mod cpu;
pub mod device;
mod driver;
pub mod error;
pub mod events;
pub mod fs;
mod init;
mod ipc;
mod net;
pub mod power;
pub mod prelude;
pub mod process;
mod sched;
pub mod security;
mod syscall;
mod thread;
mod time;
pub mod util;
// TODO: Add vDSO support for LoongArch.
#[cfg(not(target_arch = "loongarch64"))]
mod vdso;
pub mod vm;

/// Boots the Asterinas core kernel.
pub fn boot() {
    init::main();
}
